mapper.select:
SELECT COUNT(*) FROM t_table t


        t.shop_id = #{shopId}


        1 = 1

SELECT TRIM(od.name) AS dish_name, COALESCE(SUM(CAST(od.quantity AS DECIMAL(12, 2))), 0) AS total_quantity, COALESCE(SUM(od.total_price), 0) AS total_sales, CAST(NULL AS DECIMAL(10, 2)) AS ref_cost_price, MAX(d.time) AS dish_listed_time, MAX(CASE WHEN od.name LIKE '%套餐%' OR IFNULL(od.remark,'') LIKE '%套餐%' THEN 1 ELSE 0 END) AS combo_flag FROM t_order_detail od INNER JOIN t_order o ON od.mId = o.id LEFT JOIN t_dish d ON d.id = ( SELECT MIN(d2.id) FROM t_dish d2 WHERE TRIM(d2.name) = TRIM(od.name) ) WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' ) AND od.name IS NOT NULL AND TRIM(od.name) != '' AND o.transac_status = 'success' AND (o.order_receiving IN ('rec_order', 'off_order') OR o.order_receiving IS NULL)
AND o.shop_id = #{shopId}
GROUP BY TRIM(od.name) ORDER BY total_sales DESC

SELECT DATE_FORMAT(o.order_time, '%Y-%m-%d') AS day_label, COALESCE(SUM(od.total_price), 0) AS sales, COALESCE(SUM(CAST(od.quantity AS DECIMAL(12,2))), 0) AS quantity FROM t_order_detail od INNER JOIN t_order o ON od.mId = o.id INNER JOIN t_dish d ON d.id = ( SELECT MIN(d2.id) FROM t_dish d2 WHERE TRIM(d2.name) = TRIM(od.name) ) WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND d.time IS NOT NULL AND d.time >= #{startTime} AND d.time <= #{endTime} AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' ) AND o.transac_status = 'success' AND (o.order_receiving IN ('rec_order', 'off_order') OR o.order_receiving IS NULL)
AND o.shop_id = #{shopId}
GROUP BY DATE_FORMAT(o.order_time, '%Y-%m-%d') ORDER BY day_label ASC

SELECT DATE_FORMAT(t.bd, '%Y-%m-%d') AS day_label, COALESCE(SUM(t.line_sales), 0) AS sales, COALESCE(SUM(t.line_qty), 0) AS quantity FROM ( SELECT od.total_price AS line_sales, CAST(od.quantity AS DECIMAL(12,2)) AS line_qty, AS bd FROM t_order_detail od INNER JOIN t_order o ON od.mId = o.id INNER JOIN t_dish d ON d.id = ( SELECT MIN(d2.id) FROM t_dish d2 WHERE TRIM(d2.name) = TRIM(od.name) ) WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND d.time IS NOT NULL AND d.time >= #{startTime} AND d.time <= #{endTime} AND ( (od.total_price IS NOT NULL AND od.total_price > 0) OR IFNULL(od.line_type,'') = 'combo_component' ) AND o.transac_status = 'success' AND (o.order_receiving IN ('rec_order', 'off_order') OR o.order_receiving IS NULL)
AND o.shop_id = #{shopId}
) t GROUP BY DATE_FORMAT(t.bd, '%Y-%m-%d') ORDER BY day_label ASC

SELECT IFNULL(NULLIF(TRIM(od.selectedSpicy), ''), '(未标注)') AS taste_label, COALESCE(SUM(CAST(od.quantity AS DECIMAL(12,2))), 0) AS quantity, COUNT(*) AS line_count FROM t_order_detail od INNER JOIN t_order o ON od.mId = o.id WHERE o.order_time >= #{startTime} AND o.order_time < #{endTime} AND o.transac_status = 'success' AND (o.order_receiving IN ('rec_order', 'off_order') OR o.order_receiving IS NULL)
AND o.shop_id = #{shopId}
GROUP BY IFNULL(NULLIF(TRIM(od.selectedSpicy), ''), '(未标注)') ORDER BY quantity DESC LIMIT 50

SELECT c.id AS coupon_id, c.coupon_name AS coupon_name, (SELECT COUNT(*) FROM t_user_coupon uc WHERE uc.coupon_id = c.id AND uc.get_time >= #{startTime} AND uc.get_time <= #{endTime}) AS granted_in_range, (SELECT COUNT(*) FROM t_user_coupon uc WHERE uc.coupon_id = c.id AND uc.status = 1 AND uc.use_time IS NOT NULL AND uc.use_time >= #{startTime} AND uc.use_time <= #{endTime}) AS used_in_range, (SELECT COALESCE(SUM(), 0) FROM t_user_coupon uc2 INNER JOIN t_order o ON o.order_no = uc2.order_no WHERE uc2.coupon_id = c.id AND uc2.status = 1 AND uc2.use_time IS NOT NULL AND uc2.use_time >= #{startTime} AND uc2.use_time <= #{endTime} AND o.transac_status = 'success' AND (o.order_receiving IN ('rec_order', 'off_order') OR o.order_receiving IS NULL)
AND o.shop_id = #{shopId}
) AS driven_net_revenue FROM t_coupon c WHERE EXISTS ( SELECT 1 FROM t_user_coupon uc0 WHERE uc0.coupon_id = c.id AND ( (uc0.get_time >= #{startTime} AND uc0.get_time <= #{endTime}) OR (uc0.use_time IS NOT NULL AND uc0.use_time >= #{startTime} AND uc0.use_time <= #{endTime}) ) )

SELECT a.id AS activity_id, a.name AS activity_name, CAST(NULL AS DECIMAL(12, 2)) AS budget_amount, COUNT(DISTINCT i.user_id) AS traffic_users, SUM(CASE WHEN i.interaction_type = 'click' THEN 1 ELSE 0 END) AS click_count, SUM(CASE WHEN i.interaction_type = 'show' THEN 1 ELSE 0 END) AS show_count, ( SELECT COALESCE(SUM(), 0) FROM t_order o2 WHERE o2.merchantId = '1' AND o2.transac_status = 'success' AND (o2.order_receiving IN ('rec_order', 'off_order') OR o2.order_receiving IS NULL) AND o2.order_time >= GREATEST(#{startTime}, a.start_time) AND o2.order_time <= LEAST(#{endTime}, IFNULL(a.end_time, '2099-12-31 23:59:59'))
AND o2.shop_id = #{shopId}
) AS overlap_net_revenue FROM t_activity_popup a LEFT JOIN t_user_activity_interaction i ON ( TRIM(i.activity_id) = CAST(a.id AS CHAR) OR (i.activity_id REGEXP '^[0-9]+$' AND CAST(i.activity_id AS UNSIGNED) = a.id) ) AND i.interaction_time IS NOT NULL AND TRIM(i.interaction_time) != '' AND i.interaction_time >= #{startTime} AND i.interaction_time <= #{endTime} WHERE a.start_time <= #{endTime} AND IFNULL(a.end_time, '2099-12-31') >= #{startTime}
AND ( a.apply_shop_ids IS NULL OR TRIM(a.apply_shop_ids) = '' OR TRIM(a.apply_shop_ids) = '[]' OR JSON_CONTAINS(a.apply_shop_ids, CAST(#{shopId} AS JSON), '$') )
GROUP BY a.id, a.name, a.start_time, a.end_time
